import{_ as p,a0 as u,w as d,s as i,ao as l,I as r,x as t,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04","title":"如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee","tag":"201504","desc":""},"relativePath":"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04.md","filePath":"[post].md"}'),s={name:"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04.md"};function h(b,e,k,m,C,g){const o=u("Link");return d(),i("div",null,[e[17]||(e[17]=l(`<h1 id="如何在ubuntu-14-04上安裝輕量級web服務器cherokee" tabindex="-1">如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee <a class="header-anchor" href="#如何在ubuntu-14-04上安裝輕量級web服務器cherokee" aria-label="Permalink to “如何在Ubuntu 14.04上安裝輕量級web服務器Cherokee”">​</a></h1><p><strong>Cherokee</strong> 是一個免費，開源，高性能輕量級的全功能web服務器，支持大部分主流操作系統(Linux、 Mac OS X、 Solaris 和 BSD)。它支持TLS/SSL、FastCGI、 SCGI、 PHP、 uWSGI、 SSI、 CGI、 LDAP、 HTTP代理、 視頻流處理、 內容緩存、 流量控制、 虛擬主機、Apache兼容的日誌文件，以及負載均衡等功能。</p><p>今天我們介紹一下怎樣在Ubuntu Server 14.04 LTS安裝和配置輕量級的web服務器Cherokee，只需要注意修改軟件源列表，同樣適用於Ubuntu12.04，12.10和13.04。</p><p>在Ubuntu Server上逐步安裝和配置Cherokee</p><h3 id="_1-更新ubuntu軟件包索引" tabindex="-1">1. 更新Ubuntu軟件包索引 <a class="header-anchor" href="#_1-更新ubuntu軟件包索引" aria-label="Permalink to “1. 更新Ubuntu軟件包索引”">​</a></h3><p>首先登陸Ubuntu Server，執行以下命令，更新Ubuntu Server的軟件源並安裝可用的更新。</p><pre><code>sudo apt-get update

sudo apt-get upgrade
</code></pre><h3 id="_2-加入-ppa" tabindex="-1">2. 加入 PPA <a class="header-anchor" href="#_2-加入-ppa" aria-label="Permalink to “2. 加入 PPA”">​</a></h3><p>通過運行以下命令增加Cherokee的PPA</p><pre><code>sudo add-apt-repository ppa:cherokee-webserver

sudo apt-get update
</code></pre><p>對於運行14.04版本的服務器還需要執行以下步驟</p><pre><code>cd /etc/apt/sources.list.d

nano cherokee-webserver-ppa-trusty.list
</code></pre><p>用<code>deb http://ppa.launchpad.net/cherokee-webserver/ppa/ubuntu saucy main</code> 替換 <code>deb http://ppa.launchpad.net/cherokee-webserver/ppa/ubuntu trusty main</code></p><p><strong>再次運行命令:</strong></p><pre><code>sudo apt-get update
</code></pre><h3 id="_3-使用apt-get安裝cherokee" tabindex="-1">3. 使用apt-get安裝Cherokee <a class="header-anchor" href="#_3-使用apt-get安裝cherokee" aria-label="Permalink to “3. 使用apt-get安裝Cherokee”">​</a></h3><p>使用如下命令安裝Cherokee和SSL模組</p><pre><code>sudo apt-get install cherokee cherokee-admin cherokee-doc libcherokee-mod-libssl libcherokee-mod-streaming libcherokee-mod-rrd
</code></pre><h3 id="_4-配置cherokee" tabindex="-1">4. 配置Cherokee <a class="header-anchor" href="#_4-配置cherokee" aria-label="Permalink to “4. 配置Cherokee”">​</a></h3><p>重啓Cherokee服務：</p><pre><code>sudo service cherokee start
</code></pre><p>使用Cherokee最大的好處就是能通過一個簡單易用的web界面 cherokee-admin 來管理所有的配置選項。推薦通過瀏覽器來管理Cherokee。使用如下命令啓動cherokee-admin</p><pre><code>sudo cherokee-admin
</code></pre><p><strong>注意： cherokee-admin 會顯示用户名，一次性密碼和web管理界面地址。</strong></p><p><strong>請記錄下這個一次性密碼，登錄到管理界面時需要它。</strong></p><p>默認情況下，只能通過localhost訪問Cherokee-admin，如果需要通過其它網絡地址來訪問，可以使用‘<strong>-b</strong>’參數。如果不指定任何IP地址，Cherokee-admin會自動監聽所有網絡端口。然後就可以通過網絡訪問Cherokee-admin</p><pre><code>sudo cherokee-admin -b
</code></pre><p>通過指定IP地址訪問Cherokee-admin</p><pre><code>sudo cherokee-admin -b 192.168.1.102
</code></pre><h3 id="_5-瀏覽cherokee-admin面板" tabindex="-1">5. 瀏覽cherokee-admin面板 <a class="header-anchor" href="#_5-瀏覽cherokee-admin面板" aria-label="Permalink to “5. 瀏覽cherokee-admin面板”">​</a></h3>`,30)),r("p",null,[e[1]||(e[1]=t("在你喜歡的瀏覽器中輸入地址",-1)),e[2]||(e[2]=r("code",null,"http://主機名或 IP 地址:9090/",-1)),e[3]||(e[3]=t("就可以進入控制面板了。例如我的是",-1)),n(o,{href:"http://127.0.0.1:9090/%EF%BC%8C%E5%9C%A8%E7%80%8F%E8%A6%BD%E5%99%A8%E4%B8%AD%E9%A1%AF%E7%A4%BA%E5%A6%82%E4%B8%8B%E5%9C%96"},{default:a(()=>[...e[0]||(e[0]=[t("http://127.0.0.1:9090/，在瀏覽器中顯示如下圖",-1)])]),_:1})]),e[18]||(e[18]=r("p",null,[r("img",{src:"http://blog.linoxide.com/wp-content/uploads/2014/12/cherokee-admin.png",alt:"cherokee-admin-panel"})],-1)),e[19]||(e[19]=r("p",null,"好了，到這裏我們已經成功地在Ubuntu Server上安裝和配置了Cherokee。",-1)),e[20]||(e[20]=r("hr",null,null,-1)),r("p",null,[e[5]||(e[5]=t("via: ",-1)),n(o,{href:"http://linoxide.com/ubuntu-how-to/install-cherokee-lightweight-web-server-ubuntu-14-04/"},{default:a(()=>[...e[4]||(e[4]=[t("http://linoxide.com/ubuntu-how-to/install-cherokee-lightweight-web-server-ubuntu-14-04/",-1)])]),_:1})]),r("p",null,[e[9]||(e[9]=t("作者：",-1)),n(o,{href:"http://linoxide.com/author/arunp/"},{default:a(()=>[...e[6]||(e[6]=[t("Arun Pyasi",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),n(o,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[7]||(e[7]=[t("ictlyh",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[14]||(e[14]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const S=p(s,[["render",h]]);export{f as __pageData,S as default};
